//! Fixture parity and regression tests for the Dia family.
//!
//! Fixtures live in `testdata/tts_dia/`, regenerated by
//! `tools/gen_dia_fixtures.py` against the pinned mlx-audio commit.
//! The e2e cases replay the reference greedy decode: every step asserts
//! the Rust per-channel argmax against the recorded natural selection
//! before applying the fixture's scripted override (the EOS timing a
//! seeded tiny model cannot produce naturally), then the code grid and
//! the DAC waveform pin the full loop.

use std::path::{Path, PathBuf};

use serde_json::Value;

use super::audio::{apply_audio_delay, codebook_to_audio, revert_audio_delay};
use super::{Greedy, Model, SampleSource};
use crate::codec::descript::{Dac, DacConfig};
use turbospark_model_io::safetensors::SafetensorsFile;

fn testdata(name: &str) -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("testdata/tts_dia")
        .join(name)
}

fn read_json(path: &Path) -> Value {
    let text = std::fs::read_to_string(path).expect("fixture json");
    serde_json::from_str(&text).expect("fixture json")
}

fn f32_vec(value: &Value) -> Vec<f32> {
    value
        .as_array()
        .expect("values")
        .iter()
        .map(|v| v.as_f64().expect("value") as f32)
        .collect()
}

fn i32_rows(value: &Value) -> Vec<Vec<i32>> {
    value
        .as_array()
        .expect("rows")
        .iter()
        .map(|row| {
            row.as_array()
                .expect("row")
                .iter()
                .map(|v| v.as_i64().expect("int") as i32)
                .collect()
        })
        .collect()
}

fn read_npy(path: &Path) -> Vec<f32> {
    let bytes = std::fs::read(path).expect("npy");
    assert_eq!(&bytes[..6], b"\x93NUMPY");
    let header_len = u16::from_le_bytes([bytes[8], bytes[9]]) as usize;
    bytes[10 + header_len..]
        .chunks_exact(4)
        .map(|c| f32::from_le_bytes([c[0], c[1], c[2], c[3]]))
        .collect()
}

fn max_abs_diff(a: &[f32], b: &[f32]) -> f32 {
    assert_eq!(a.len(), b.len(), "length mismatch");
    a.iter()
        .zip(b)
        .map(|(x, y)| (x - y).abs())
        .fold(0.0f32, f32::max)
}

/// Measured against the fixture waveforms when the gate was frozen;
/// the tiny DAC decode dominates the error budget.
const WAVEFORM_TOLERANCE: f32 = 2e-4;

fn load_dac(case: &str) -> Dac {
    let dir = testdata(case);
    let config = read_json(&dir.join("dac_config.json"));
    let config = DacConfig::from_json(&config).expect("dac config");
    let file = SafetensorsFile::open(&dir.join("dac.safetensors")).expect("dac weights");
    Dac::load(config, &file).expect("dac loads")
}

/// The scripted per-step source: the Rust natural argmax must equal the
/// recorded reference natural selection every step, then the fixture's
/// override rule applies exactly as it did in Python.
/// The replay source: the Rust per-channel argmax must equal the
/// recorded reference natural selection over the clean prefix (before
/// the first post-EOS add pushes decoder inputs out of vocabulary, where
/// the reference embedding reads undefined rows); the recorded
/// prediction is then fed back so the code grid stays pinned over the
/// countdown region too.
struct ScriptedSource {
    natural: Vec<Vec<i32>>,
    pred: Vec<Vec<i32>>,
    natural_steps: usize,
    step: usize,
}

impl ScriptedSource {
    fn new(traces: &Value) -> Self {
        let steps = traces["steps"].as_array().expect("steps");
        Self {
            natural: steps
                .iter()
                .map(|s| {
                    s["natural"]
                        .as_array()
                        .expect("natural")
                        .iter()
                        .map(|v| v.as_i64().expect("int") as i32)
                        .collect()
                })
                .collect(),
            pred: steps
                .iter()
                .map(|s| {
                    s["pred"]
                        .as_array()
                        .expect("pred")
                        .iter()
                        .map(|v| v.as_i64().expect("int") as i32)
                        .collect()
                })
                .collect(),
            natural_steps: traces["natural_steps"]
                .as_u64()
                .unwrap_or(steps.len() as u64) as usize,
            step: 0,
        }
    }
}

impl SampleSource for ScriptedSource {
    fn sample(
        &mut self,
        logits: &[f32],
        channels: usize,
        vocab: usize,
        _temperature: f32,
    ) -> crate::Result<Vec<i32>> {
        assert!(
            self.step < self.natural.len(),
            "step {} past the {} recorded",
            self.step,
            self.natural.len()
        );
        if self.step < self.natural_steps {
            let natural: Vec<i32> = (0..channels)
                .map(|c| super::super::sampling::argmax(&logits[c * vocab..(c + 1) * vocab]) as i32)
                .collect();
            assert_eq!(
                natural, self.natural[self.step],
                "natural argmax mismatch at step {}",
                self.step
            );
        }
        let pred = self.pred[self.step].clone();
        self.step += 1;
        Ok(pred)
    }
}

#[test]
fn config_defaults_match_the_reference() {
    let config = serde_json::json!({
        "model": {
            "encoder": {"n_layer": 1, "n_embd": 8, "n_hidden": 8, "n_head": 2, "head_dim": 4},
            "decoder": {"n_layer": 1, "n_embd": 8, "n_hidden": 8, "gqa_query_heads": 4,
                        "kv_heads": 2, "gqa_head_dim": 4, "cross_query_heads": 2,
                        "cross_head_dim": 4}
        },
        "data": {"text_length": 100, "audio_length": 300}
    });
    let config = super::DiaConfig::from_json(&config).expect("config parses");
    assert_eq!(config.data.channels, 9);
    assert_eq!(config.data.text_pad_value, 0);
    assert_eq!(config.data.audio_eos_value, 1024);
    assert_eq!(config.data.audio_pad_value, 1025);
    assert_eq!(config.data.audio_bos_value, 1026);
    assert_eq!(
        config.data.delay_pattern,
        vec![0, 8, 9, 10, 11, 12, 13, 14, 15]
    );
    // Lengths round up to a multiple of 128.
    assert_eq!(config.data.text_length, 128);
    assert_eq!(config.data.audio_length, 384);
    assert_eq!(config.model.tgt_vocab_size, 1028);
    assert_eq!(config.model.sample_rate, 44100);
    assert_eq!(config.model.normalization_layer_epsilon, 1.0e-5);
    assert_eq!(config.version, "1.0", "the default version string applies");
}

#[test]
fn bf16_activation_configs_are_refused() {
    let config = serde_json::json!({
        "model": {
            "encoder": {"n_layer": 1, "n_embd": 8, "n_hidden": 8, "n_head": 2, "head_dim": 4},
            "decoder": {"n_layer": 1, "n_embd": 8, "n_hidden": 8, "gqa_query_heads": 4,
                        "kv_heads": 2, "gqa_head_dim": 4, "cross_query_heads": 2,
                        "cross_head_dim": 4}
        },
        "training": {"dtype": "bfloat16"},
        "data": {"text_length": 128, "audio_length": 128}
    });
    assert!(super::DiaConfig::from_json(&config).is_err());
}

#[test]
fn text_tokenization_and_turn_splitting_match_the_reference() {
    let traces = read_json(&testdata("text/traces.json"));
    let model = Model::open(&testdata("text")).expect("model loads");
    let (tokens, masks) = model.prepare_text(traces["script"].as_str().expect("script"));
    let want_tokens: Vec<i32> = traces["src_tokens"]
        .as_array()
        .expect("tokens")
        .iter()
        .map(|v| v.as_i64().expect("int") as i32)
        .collect();
    assert_eq!(tokens[1], want_tokens, "conditional byte tokens");
    assert!(
        tokens[0].iter().all(|&t| t == 0),
        "the unconditional row is all pad"
    );
    let want_mask: Vec<bool> = traces["padding_mask"]
        .as_array()
        .expect("mask")
        .iter()
        .map(|v| v.as_bool().expect("bool"))
        .collect();
    assert_eq!(masks[1], want_mask);
    // [S1]/[S2] markers collapse to single bytes.
    assert!(tokens[1].contains(&1) && tokens[1].contains(&2));

    let splits: Vec<String> = traces["split_turns"]
        .as_array()
        .expect("turns")
        .iter()
        .map(|v| v.as_str().expect("str").to_owned())
        .collect();
    assert_eq!(
        Model::split_turns(traces["split_script"].as_str().expect("script")),
        splits,
        "three pairs merge into two segments"
    );
}

#[test]
fn delay_revert_and_clamp_match_the_reference() {
    let traces = read_json(&testdata("delay/traces.json"));
    let dac = load_dac("delay");
    let delay: Vec<usize> = vec![0, 8, 9, 10, 11, 12, 13, 14, 15];
    let input = i32_rows(&traces["input_grid"]);
    let delayed = apply_audio_delay(&input, &delay, 1025, 1026);
    assert_eq!(delayed, i32_rows(&traces["delayed_grid"]));
    let reverted = revert_audio_delay(&input, &delay, 0);
    assert_eq!(reverted, i32_rows(&traces["reverted_grid"]));
    let (wave, _clamped) =
        codebook_to_audio(&i32_rows(&traces["codebook_input"]), &dac, &delay, 64).expect("decodes");
    let want = f32_vec(&traces["waveform"]);
    assert_eq!(wave.len(), want.len());
    assert!(
        max_abs_diff(&wave, &want) < WAVEFORM_TOLERANCE,
        "delay-case waveform"
    );
}

fn run_case(case: &str) {
    let traces = read_json(&testdata(case).join("traces.json"));
    let mut model = Model::open(&testdata(case)).expect("model loads");
    let dac = load_dac(case);
    let params = super::GenerateParams {
        max_tokens: Some(traces["max_tokens"].as_u64().expect("max") as usize),
        ..Default::default()
    };
    let mut source = ScriptedSource::new(&traces);
    let results = model
        .generate(
            traces["prompt"].as_str().expect("prompt"),
            &params,
            &dac,
            &mut source,
            None,
            None,
        )
        .expect("generate runs");
    assert_eq!(results.len(), 1, "{case}: one segment");
    let got = &results[0];
    assert_eq!(
        got.codes,
        i32_rows(&traces["codes"]),
        "{case}: sliced code grid"
    );
    assert_eq!(
        got.token_count,
        traces["token_count"].as_u64().expect("tokens") as usize,
        "{case}: token count"
    );
    let want = f32_vec(&traces["waveform"]);
    assert_eq!(got.samples.len(), want.len(), "{case}: sample count");
    assert!(
        max_abs_diff(&got.samples, &want) < WAVEFORM_TOLERANCE,
        "{case}: waveform"
    );
}

#[test]
fn greedy_eos_run_matches_the_reference() {
    run_case("generate");
}

#[test]
fn budget_run_matches_the_reference() {
    run_case("budget");
}

#[test]
fn midstop_eos_adds_match_the_reference() {
    run_case("midstop");
}

#[test]
fn voice_prompt_prefill_matches_the_reference() {
    let traces = read_json(&testdata("voice/traces.json"));
    let mut model = Model::open(&testdata("voice")).expect("model loads");
    let dac = load_dac("voice");
    let params = super::GenerateParams {
        max_tokens: Some(traces["max_tokens"].as_u64().expect("max") as usize),
        ..Default::default()
    };
    let mut source = ScriptedSource::new(&traces);
    let results = model
        .generate(
            traces["prompt"].as_str().expect("prompt"),
            &params,
            &dac,
            &mut source,
            Some(&f32_vec(&traces["ref_audio"])),
            Some(traces["ref_text"].as_str().expect("ref_text")),
        )
        .expect("generate runs");
    assert_eq!(results.len(), 1);
    let got = &results[0];
    assert_eq!(got.codes, i32_rows(&traces["codes"]), "sliced code grid");
    assert_eq!(
        got.token_count,
        traces["token_count"].as_u64().expect("tokens") as usize
    );
    let want = f32_vec(&traces["waveform"]);
    assert_eq!(got.samples.len(), want.len());
    assert!(max_abs_diff(&got.samples, &want) < WAVEFORM_TOLERANCE);
    // The prompt codes themselves ride the DAC encode + delay.
    let prompt = super::audio::audio_to_codebook(
        &dac,
        &f32_vec(&traces["ref_audio"]),
        &[0, 8, 9, 10, 11, 12, 13, 14, 15],
        1026,
        1025,
    )
    .expect("prompt codes");
    assert_eq!(prompt, i32_rows(&traces["prompt_codes"]));
}

#[test]
fn sampling_filter_chain_matches_the_reference() {
    let traces = read_json(&testdata("sampling/traces.json"));
    let logits = read_npy(&testdata("sampling/logits.npy"));
    let vocab = 1028usize;
    let channels = logits.len() / vocab;
    assert_eq!(channels, 9);

    // Temperature 0 is the per-channel argmax.
    let greedy: Vec<i32> = (0..channels)
        .map(|c| super::super::sampling::argmax(&logits[c * vocab..(c + 1) * vocab]) as i32)
        .collect();
    let want_argmax: Vec<i32> = traces["argmax"]
        .as_array()
        .expect("argmax")
        .iter()
        .map(|v| v.as_i64().expect("int") as i32)
        .collect();
    assert_eq!(greedy, want_argmax);

    // The make_sampler chain: top-p on the raw CFG logits, then top-k.
    let temperature = traces["temperature"].as_f64().expect("temp") as f32;
    let top_p = traces["top_p"].as_f64().expect("top_p") as f32;
    let top_k = traces["top_k"].as_u64().expect("top_k") as usize;
    let mut filtered = logits.clone();
    for c in 0..channels {
        let row = &mut filtered[c * vocab..(c + 1) * vocab];
        crate::tts::sampling::apply_top_p(row, top_p);
        crate::tts::sampling::apply_top_k(row, top_k).expect("top_k");
    }
    let want_p = read_npy(&testdata("sampling/filtered_top_p.npy"));
    let want_pk = read_npy(&testdata("sampling/filtered_top_p_top_k.npy"));
    // The -inf masking must land on exactly the same entries; compare
    // the finite parts and the support sets.
    for (got, want) in filtered.iter().zip(&want_pk) {
        assert_eq!(got.is_finite(), want.is_finite(), "support entry");
    }
    let finite = |a: &[f32]| -> Vec<f32> { a.iter().copied().filter(|v| v.is_finite()).collect() };
    assert!(
        max_abs_diff(&finite(&filtered), &finite(&want_pk)) < 1e-3,
        "filtered logits"
    );

    // The recorded draw came from the MLX RNG; the Rust draw uses the
    // crate-local threefry sequence, so the assertion is support
    // membership, not the exact token.
    let drawn: Vec<usize> = traces["drawn"]
        .as_array()
        .expect("drawn")
        .iter()
        .map(|v| v.as_u64().expect("int") as usize)
        .collect();
    for (c, &token) in drawn.iter().enumerate() {
        assert!(
            filtered[c * vocab + token].is_finite(),
            "drawn token {token} outside the filtered support"
        );
    }
    let _ = want_p;
    let _ = temperature;
}

#[test]
fn empty_decode_refuses_like_the_reference_crash() {
    // The reference raises inside the quantizer when fewer than 30
    // frames survive the tail trim; the port refuses with an error.
    let dac = load_dac("generate");
    let delay: Vec<usize> = vec![0, 8, 9, 10, 11, 12, 13, 14, 15];
    let codes = vec![vec![10i32; 20]; 9];
    assert!(codebook_to_audio(&codes, &dac, &delay, 64).is_err());
}

#[test]
fn greedy_source_takes_the_first_argmax() {
    let mut logits = vec![0.0f32; 2 * 8];
    logits[3] = 5.0;
    logits[8 + 5] = 4.0;
    let mut greedy = Greedy;
    assert_eq!(
        greedy.sample(&logits, 2, 8, 0.0).unwrap(),
        vec![3, 5],
        "first maximal index wins per channel"
    );
}

#[test]
fn sampled_source_propagates_top_k_errors() {
    // top_k must lie in (0, len); top_k == len used to be dropped by `let _`
    // and the row sampled unfiltered. It is now an error.
    let logits = vec![0.0f32; 8];
    let mut sampled = super::Sampled::new(0, 1.0, 8);
    assert!(sampled.sample(&logits, 1, 8, 1.0).is_err());
    let mut ok = super::Sampled::new(0, 1.0, 4);
    assert_eq!(ok.sample(&logits, 1, 8, 1.0).unwrap().len(), 1);
}

#[test]
fn self_cache_holds_a_voice_prompt_longer_than_the_budget() {
    // Prefill writes 1 + prompt_frames positions, then each of max_tokens
    // decode steps appends one. A prompt longer than the budget used to
    // hit "KV cache full" because the cache was sized from max_tokens.
    let (heads, head_dim) = (1usize, 2usize);
    let max_tokens = 4usize;
    let prompt_frames = 10usize;
    let capacity = super::self_cache_capacity(prompt_frames, max_tokens).unwrap();
    let mut cache = super::layers::KvStore::new(heads, capacity, head_dim);
    let prefill_len = 1 + prompt_frames;
    let block = vec![0.0f32; 2 * heads * prefill_len * head_dim];
    cache.prefill(&block, &block, prefill_len);
    let step = vec![0.0f32; 2 * heads * head_dim];
    for _ in 0..max_tokens {
        cache.update(&step, &step);
    }
    assert_eq!(cache.len, prefill_len + max_tokens);
}

#[test]
fn self_cache_capacity_refuses_overflow() {
    assert_eq!(super::self_cache_capacity(3, 5).unwrap(), 9);
    assert!(super::self_cache_capacity(usize::MAX, 1).is_err());
    assert!(super::self_cache_capacity(0, usize::MAX).is_err());
}

#[test]
fn zero_kv_heads_is_refused_at_load() {
    // The GQA divisibility check divides by kv_heads; zero must be a
    // BadConfig, not a divide-by-zero panic.
    let json = serde_json::json!({
        "model": {
            "encoder": {"n_layer": 1, "n_embd": 8, "n_hidden": 8, "n_head": 2, "head_dim": 4},
            "decoder": {"n_layer": 1, "n_embd": 8, "n_hidden": 8, "gqa_query_heads": 4,
                        "kv_heads": 2, "gqa_head_dim": 4, "cross_query_heads": 2,
                        "cross_head_dim": 4}
        },
        "data": {"text_length": 100, "audio_length": 300}
    });
    let mut config = super::DiaConfig::from_json(&json).expect("config parses");
    config.model.decoder.kv_heads = 0;
    assert!(Model::validate(&config).is_err());
}

#[test]
fn split_turns_handles_single_pairs_and_merges_pairs() {
    let one = Model::split_turns("[S1] hi [S2] there");
    assert_eq!(one, vec!["[S1] hi [S2] there"]);
    let merged = Model::split_turns("[S1] a [S2] b [S1] c [S2] d [S1] e [S2] f");
    assert_eq!(merged.len(), 2);
    assert_eq!(merged[0], "[S1] a [S2] b [S1] c [S2] d");
    assert_eq!(merged[1], "[S1] e [S2] f");
    assert!(Model::split_turns("no markers here").is_empty());
}
